context_info = ()
for d in context:
    q = "You are given a document. Extract any fungi mentioned that could match ALL of the following clues. For each candidate, give a compact entry with: Common English name(s) (highlight a two-word English name if present), Scientific name, Key morphology (especially: raised/scaly cap), Fruiting habit (clusters after rainfall), Size (large?), Culinary/market value (highly valued?), Medicinal claims (potential antifungal properties?), Who named it scientifically (authorship, and whether by a French expert in the 1980s), Any link between the fungus's non-scientific English name and the name of a character in a 1980s film that was said to have been inspired by a bronze statuette from the 1970s (provide the film title, the character name, and the statuette details), and short supporting quotes from the document.\nKeep each candidate to 5-10 lines.\n\nBEGIN_DOCUMENT\n" + d + "\nEND_DOCUMENT"
    r = llm_query(q)
    context_info = context_info + (r,)

synth = "We need to identify a rare/uncommon, large fungus that:\n- Typically appears in clusters after rainfall\n- Has raised scales on its cap\n- Is highly valued\n- Was scientifically named (or reclassified) by a French expert in the 1980s\n- Is said to possess potential antifungal properties\n- Has a non-scientific English name that is the same as that of a character in a film from the 1980s\n- The film was said to have been inspired by a bronze statuette made in the 1970s\n- The answer must be a common two-word English name whose first word has three syllables and ends in a vowel.\n\nHere are extracted candidate notes from the documents:\n" + "\n\n---\n\n".join(context_info) + "\n\nTask: Choose the single fungus that satisfies ALL constraints. Return ONLY the two-word common English name, no explanations, no punctuation, no extra words. Confirm internally that the first word has three syllables and ends in a vowel."
final_answer = llm_query(synth)
return_result(final_answer)